<?php $activeMenu='pppoe';$pppoeView='history';?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PPPoE Traffic History - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css?v=8"><link rel="stylesheet" href="../assets/css/common.css?v=8"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><link rel="stylesheet" href="../assets/css/pppoe_subpage.css?v=1"></head><body><?php require_once '../includes/sidebar.php';?><main class="main-content ppp-subpage"><header class="ppp-head"><div><h1 class="ppp-title">PPPoE Traffic History</h1><div class="ppp-sub">Pilih user untuk melihat histori traffic detail</div></div><div class="ppp-actions"><div class="ppp-btn" id="period">24 Jam</div></div></header><section class="ppp-card"><div class="ppp-card-head"><div><h2>Users dengan histori traffic</h2><small id="meta">Memuat...</small></div><div class="ppp-actions"><button class="ppp-btn" data-r="1h">1H</button><button class="ppp-btn" data-r="6h">6H</button><button class="ppp-btn primary" data-r="24h">24H</button><button class="ppp-btn" data-r="7d">7D</button><button class="ppp-btn" data-r="30d">30D</button></div></div><div class="ppp-body"><div class="ppp-table-wrap"><table class="ppp-table"><thead><tr><th>#</th><th>Username</th><th>Profile</th><th>Total Traffic</th><th>Download</th><th>Upload</th><th>Records</th><th>Action</th></tr></thead><tbody id="rows"><tr><td colspan="8">Memuat...</td></tr></tbody></table></div></div></section></main><script>let range='24h',api='../api/pppoe_ranking.php',esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])),bytes=n=>{n=Number(n)||0;let u=['B','KB','MB','GB','TB'],i=0;while(n>=1024&&i<4){n/=1024;i++}return n.toFixed(n>=100?0:n>=10?1:2)+' '+u[i]};async function load(){document.querySelectorAll('[data-r]').forEach(b=>b.classList.toggle('primary',b.dataset.r===range));try{let r=await fetch(api+'?range='+range+'&t='+Date.now(),{cache:'no-store'}),d=await r.json();if(!d.success)throw Error(d.message||'Gagal');let a=d.users||[];document.getElementById('meta').textContent=(a.length||0)+' user • '+range;document.getElementById('period').textContent=range==='1h'?'1 Jam':range==='6h'?'6 Jam':range==='7d'?'7 Hari':range==='30d'?'30 Hari':'24 Jam';document.getElementById('rows').innerHTML=a.length?a.map((x,i)=>`<tr><td>${i+1}</td><td><b>${esc(x.username)}</b></td><td>${esc(x.profile||'-')}</td><td class="num"><b>${bytes(x.total_bytes)}</b></td><td class="num">${bytes(x.download_bytes)}</td><td class="num">${bytes(x.upload_bytes)}</td><td>${x.records||0}</td><td><a class="ppp-btn primary" href="./history.php?username=${encodeURIComponent(x.username)}">History</a> <a class="ppp-btn" href="./user.php?username=${encodeURIComponent(x.username)}">Detail</a></td></tr>`).join(''):'<tr><td colspan="8">Belum ada histori.</td></tr>'}catch(e){document.getElementById('meta').textContent=e.message;document.getElementById('rows').innerHTML='<tr><td colspan="8">Data belum tersedia.</td></tr>'}}document.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{range=b.dataset.r;load()});load();setInterval(()=>document.visibilityState==='visible'&&load(),10000);</script></body></html>